/* Kanalinsikter: all file processing stays in the browser. */
const state={files:{Facebook:null,Instagram:null},posts:[],rules:{},images:{},weights:{reach:.7,engagement:.3}};
const $=id=>document.getElementById(id);const fmt=n=>new Intl.NumberFormat('sv-SE',{maximumFractionDigits:0}).format(n||0);const pct=n=>new Intl.NumberFormat('sv-SE',{style:'percent',maximumFractionDigits:1}).format(n||0);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const safeUrl=v=>/^https:\/\//i.test(String(v||''))?String(v):'#';
const aliases={id:['Publicerings-id','Post ID'],date:['Publiceringstid','Publish time','Datum'],url:['Permalänk','Permalink'],image:['Bild-URL','Bildadress','Media URL','Media URL-adress','Thumbnail URL','Miniatyrbild'],type:['Inläggstyp','Post type','Medietyp'],text:['Beskrivning','Titel','Description','Caption'],reach:['Räckvidd','Reach'],views:['Visningar','Views'],likes:['Reaktioner','Gilla-markeringar','Reactions','Likes'],comments:['Kommentarer','Comments'],shares:['Delningar','Shares'],saves:['Sparade objekt','Saves'],clicks:['Totalt antal klick','Klick','Clicks'],follows:['Följer','Follows'],paid:['Räckvidd från Marknadsförda inlägg','Paid reach','Marknadsförd räckvidd']};
function value(row,key){const h=aliases[key].find(k=>Object.prototype.hasOwnProperty.call(row,k));return h?row[h]:''}function textValue(row){const candidates=aliases.text.filter(k=>Object.prototype.hasOwnProperty.call(row,k)).map(k=>String(row[k]??'').trim()).filter(v=>v&&!/^\d+$/.test(v));return candidates.sort((a,b)=>b.length-a.length)[0]||''}function number(v){const n=Number(String(v??'').replace(/\s/g,'').replace(',','.'));return Number.isFinite(n)?n:0}function median(a){const v=a.filter(Number.isFinite).sort((x,y)=>x-y);if(!v.length)return 0;const m=Math.floor(v.length/2);return v.length%2?v[m]:(v[m-1]+v[m])/2}function average(a){const v=a.filter(Number.isFinite);return v.length?v.reduce((s,n)=>s+n,0)/v.length:0}function csvEscape(v){const s=String(v??'');return /[",\n]/.test(s)?`"${s.replaceAll('"','""')}"`:s}function short(s,n=92){s=String(s||'').replace(/\s+/g,' ').trim();return s.length>n?s.slice(0,n-1)+'…':s}
function parseDate(v){const s=String(v||'').trim();let m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);if(m)return new Date(+m[3],+m[1]-1,+m[2]);m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return new Date(+m[1],+m[2]-1,+m[3]);const d=new Date(s);return Number.isNaN(d.getTime())?null:d}function iso(d){return d?`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`:''}
function normalizeFormat(channel,v){const s=String(v||'').toLowerCase();if(channel==='Facebook'){if(s.includes('video')||s.includes('reel'))return'Video';if(s.includes('link')||s.includes('länk'))return'Länk';if(s.includes('status')||s.includes('text'))return'Text';return'Foto'}if(s.includes('reel'))return'Reel';if(s.includes('carousel')||s.includes('karusell'))return'Karusell';return'Bild'}
const weekdays=['Söndag','Måndag','Tisdag','Onsdag','Torsdag','Fredag','Lördag'];
function monthKey(d){return d?`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`:''}
function classifyTheme(text){const t=String(text||'').toLowerCase();const rules=[['Musik & evenemang',/konsert|festival|artist|musik|allsång|biljett|show|scen|evenemang|kent|winnerbäck/],['Sport & prestation',/sport|match|vasalopp|fotboll|lopp|tävling|skidor|pallplats/],['Barn & familj',/barn|familj|lekpark|lov|parken zoo|djur|tivoli/],['Mat & dryck',/restaurang|café|cafe|mat|lunch|middag|fika|dryck|öl|vin|smak/],['Natur & friluftsliv',/natur|vandring|cykel|kajak|sjö|bad|friluft|skog|sörmlandsleden/],['Kultur & historia',/museum|konst|kultur|historia|slott|rademacher|teater|bibliotek|promenad/],['Boende & avkoppling',/hotell|spa|övernatt|boende|relax|bastu|weekend/],['Stad & lokal stolthet',/eskilstuna|torshälla|fristadstorget|sundbyholm|lokal|stad/]];return rules.find(([,re])=>re.test(t))?.[0]||'Övrigt'}
function classifyContent(text){const t=String(text||'').toLowerCase(),has=re=>re.test(t);let contentDriver='Övrigt';if(has(/tävla om|chansen att vinna|giveaway|erbjudande|rabatt/))contentDriver='Tävling & erbjudande';else if(has(/öppnar|öppning|nyöpp|premiär|lanser|invig|nytt\b|nyhet|presenterar|klart för/))contentDriver='Nyhet & utveckling';else if(has(/vasalopp|utmärkelse|priset|prisad|vinnare|rekord|prestation|grattis|mästare|eldsjäl|porträtt|möt\b/))contentDriver='Människa & prestation';else if(has(/evenemang|konsert|festival|artist|musik|allsång|show|scen|biljett|teater|match|lopp|mästerskap|kulturnatt|veterandag|kent|winnerbäck/))contentDriver='Evenemang & artist';else if(has(/tips|guide|att göra|upptäck|utforska|lista|favorit|måste besöka/))contentDriver='Guide & tips';else if(has(/jul|nyår|valborg|påsk|midsommar|student|vår\b|sommar|höst|vinter|sportlov|påsklov|tradition/))contentDriver='Säsong & tradition';else if(has(/spa|hotell|restaurang|café|cafe|museum|slott|park|zoo|natur|vandring|bad|butik|besöksmål|upplevelse/))contentDriver='Plats & upplevelse';let news=has(/öppnar|öppning|nyöpp|premiär|lanser|invig|nyhet|presenterar|klart för/)?3:has(/nu\b|idag|i helgen|snart|kommer till|biljettsläpp|programmet/)?2:has(/jul|nyår|valborg|påsk|midsommar|student|vår\b|sommar|höst|vinter/)?1:0;let pride=has(/eskilstuna|torshälla|fristadstorget|sundbyholm|rademacher|parken zoo|munktell|vilsta|mälaren/)?2:0;if(pride&&has(/stolt|grattis|utmärkelse|vinnare|rekord|historia|tradition|vår stad|hemma/))pride=3;let human=has(/\bhan\b|\bhon\b|\bde\b|möt\b|intervju|porträtt|eldsjäl|besökare|publik|familj|artist|vinnare/)?1:0;if(has(/vasalopp|prestation|utmärkelse|rekord|mästare|berättar/))human=2;const practical=has(/datum|kl\.?\s|klockan|biljett|boka|anmäl|öppettider|läs mer|länk|program|gratis|fri entré/)?2:has(/tips|guide|att göra|i helgen|idag|imorgon|besök|upptäck/)?1:0;const triggers=[];if(news>=2)triggers.push('Nyhet');if(human)triggers.push('Människa');if(pride>=2)triggers.push('Lokal igenkänning');if(has(/laser|fyrverker|brasa|scen|konsert|festival|zoo|djur|show/))triggers.push('Spektakel');if(practical)triggers.push('Nytta');return{contentDriver,news,pride,human,practical,hypothesis:triggers.join(' + ')||'Ingen tydlig textsignal'}}
function normalize(row,channel,i){const reach=number(value(row,'reach')),likes=number(value(row,'likes')),comments=number(value(row,'comments')),shares=number(value(row,'shares')),saves=number(value(row,'saves')),paid=number(value(row,'paid'));const url=String(value(row,'url')||'').trim(),text=textValue(row),date=parseDate(value(row,'date')),cls=classifyContent(text),theme=classifyTheme(text);const key=`${channel}|${url||i}`,saved=state.rules[key]||{},allowed=['Ej specificerad','Organisk egenpublicering','Instagram Collab','Marknadsförd'];const distribution=allowed.includes(saved.distribution)?saved.distribution:(channel==='Facebook'?(paid>0?'Marknadsförd':'Organisk'):'Ej specificerad');const partner=/\D/.test(String(saved.partner||''))?String(saved.partner).trim():'';const interactions=likes+comments+shares+saves;return{key,channel,id:String(value(row,'id')||''),url,date,month:monthKey(date),weekday:date?weekdays[date.getDay()]:'',format:normalizeFormat(channel,value(row,'type')),text,reach,views:number(value(row,'views')),likes,comments,shares,saves,clicks:number(value(row,'clicks')),follows:number(value(row,'follows')),paid,interactions,engagement:reach?interactions/reach:0,distribution,partner,theme,source:`Rådata ${channel}!rad ${i+2}`,contentDriver:cls.contentDriver,finalDriver:cls.contentDriver,news:cls.news,pride:cls.pride,human:cls.human,practical:cls.practical,hypothesis:cls.hypothesis,timing:cls.news>=3?'Tydlig nyhet i texten':cls.news===2?'Aktuell information':cls.news===1?'Säsongsaktuell':'Inget tydligt nyhetsläge i texten',reviewStatus:'Automatisk hypotes',partnerStrength:partner?'Manuellt angiven partner':''}}
function requiredCheck(rows,channel){const headers=Object.keys(rows[0]||{});const missing=['date','url','reach'].filter(k=>!aliases[k].some(x=>headers.includes(x)));return{ok:!missing.length,missing,headers:headers.length,rows:rows.length,channel}}
async function readFile(file){return new Promise((resolve,reject)=>Papa.parse(file,{header:true,skipEmptyLines:'greedy',complete:r=>{if(r.errors.some(e=>e.code==='UndetectableDelimiter'))reject(new Error('CSV-avgränsaren kunde inte identifieras.'));else resolve({rows:r.data,meta:r.meta})},error:reject}))}
async function acceptFile(file,channel){if(!file)return;const el=$(channel.toLowerCase()+'State'),drop=$(channel.toLowerCase()+'Drop');el.textContent='Läser filen…';try{const parsed=await readFile(file),check=requiredCheck(parsed.rows,channel);if(!check.ok)throw new Error(`Saknar kolumn: ${check.missing.join(', ')}`);state.files[channel]={file,rows:parsed.rows,check};drop.classList.add('ready');el.textContent=`${file.name} · ${fmt(parsed.rows.length)} rader`;if(state.files.Facebook&&state.files.Instagram)analyze()}catch(e){drop.classList.remove('ready');el.textContent=`Fel: ${e.message}`}}
function eligible(p){return p.channel==='Facebook'?p.distribution==='Organisk':!p.distribution.startsWith('Marknadsförd')}function analyze(){state.posts=[...state.files.Facebook.rows.map((r,i)=>({...normalize(r,'Facebook',i),imageUrl:String(value(r,'image')||'').trim()})),...state.files.Instagram.rows.map((r,i)=>({...normalize(r,'Instagram',i),imageUrl:String(value(r,'image')||'').trim()}))];calculateScores();render();$('reviewPanel').classList.remove('hidden');$('exportPanel').classList.remove('hidden');$('analysisStatus').textContent='Analysen är redo'}
function rank(arr,v){if(arr.length<2)return 0;let n=0;for(const x of arr)if(x<=v)n++;return(n-1)/(arr.length-1)}function calculateScores(){state.posts.forEach(p=>{p.reachScore=null;p.engagementScore=null;p.goal=null});for(const channel of['Facebook','Instagram']){const group=state.posts.filter(p=>p.channel===channel&&eligible(p));const reaches=group.map(p=>p.reach).sort((a,b)=>a-b),engs=group.map(p=>p.engagement).sort((a,b)=>a-b);group.forEach(p=>{p.reachScore=rank(reaches,p.reach);p.engagementScore=rank(engs,p.engagement);p.goal=p.reachScore*state.weights.reach+p.engagementScore*state.weights.engagement})}}
function summaries(){return['Facebook','Instagram'].map(channel=>{const all=state.posts.filter(p=>p.channel===channel),organic=all.filter(eligible);return{channel,count:all.length,organic:organic.length,medianReach:median(organic.map(p=>p.reach)),medianEng:median(organic.map(p=>p.engagement))}})}function formatRows(){return[['Facebook','Foto'],['Facebook','Video'],['Facebook','Länk'],['Facebook','Text'],['Instagram','Bild'],['Instagram','Karusell'],['Instagram','Reel']].map(([channel,format])=>{const a=state.posts.filter(p=>p.channel===channel&&p.format===format&&eligible(p));return{channel,format,count:a.length,reach:median(a.map(p=>p.reach)),eng:median(a.map(p=>p.engagement))}})}
function topFive(channel){return state.posts.filter(p=>p.channel===channel&&eligible(p)).sort((a,b)=>(b.goal??-1)-(a.goal??-1)).slice(0,5)}function swedishList(items){return items.length<2?items[0]||'en tydlig relevans för målgruppen':`${items.slice(0,-1).join(', ')} och ${items.at(-1)}`}function topReason(p){const categoryReasons={'Nyhet & utveckling':'det innehåller något nytt som människor vill upptäcka och dela','Människa & prestation':'det har en tydlig person eller prestation att känna för','Evenemang & artist':'ämnet har en etablerad publik och ett tydligt förhandsintresse','Plats & upplevelse':'det gör en lokal plats eller upplevelse konkret och lockande','Guide & tips':'det ger användbar information som är värd att spara','Säsong & tradition':'det är aktuellt i rätt ögonblick och bygger på igenkänning','Tävling & erbjudande':'det har en tydlig belöning och låg tröskel för deltagande','Övrigt':'det träffar ett ämne som väcker ovanligt stort intresse'},reasons=[categoryReasons[p.finalDriver]||categoryReasons['Övrigt']];if(p.news>=2&&!reasons[0].includes('nytt'))reasons.push('det har ett tydligt nyhetsvärde');if(p.pride>=2)reasons.push('det väcker lokal stolthet eller stark igenkänning');if(p.human>=1&&!reasons[0].includes('person'))reasons.push('det har en mänsklig ingång');if(p.practical>=1&&!reasons[0].includes('användbar'))reasons.push('det hjälper mottagaren att förstå vad man kan göra härnäst');if(p.distribution==='Instagram Collab')reasons.push('samarbetspubliceringen kan ha gett tillgång till en större relevant publik');const explanation=`Vi tror att inlägget gick så bra eftersom ${swedishList(reasons.slice(0,3))}.`,evidence=p.reachScore>=.9&&p.engagementScore>=.8?'Det fick både ovanligt bred spridning och stark respons, vilket tyder på att ämnet fungerade även efter att människor stannat upp.':p.reachScore>=.9?'Resultatet drivs främst av mycket bred spridning; innehållet verkar alltså ha fångat intresse snabbt och nått långt utanför kärnpubliken.':'Den starka responsen i förhållande till räckvidden tyder på att innehållet kändes relevant för dem som såg det.',caution=p.channel==='Instagram'&&p.distribution==='Ej specificerad'?' Eftersom distributionen inte är verifierad kan vi ännu inte utesluta påverkan från Collab eller marknadsföring.':'';return`${explanation} ${evidence}${caution}`}function imageData(p){return state.images[p.key]?.dataUrl||(/^https:\/\//i.test(p.imageUrl||'')?p.imageUrl:'')}function topCard(p,i){const image=imageData(p);return`<article class="top-post-card"><div class="top-post-image ${image?'has-image':''}">${image?`<img src="${esc(image)}" alt="Bild till toppinlägg ${i+1}">`:''}<label>${image?'Byt bild':'Lägg till bild'}<input class="top-image-input" type="file" accept="image/png,image/jpeg" data-key="${esc(p.key)}"></label></div><div><div class="top-post-meta"><span class="top-post-rank">${i+1}</span><span>${iso(p.date)} · ${p.format} · ${fmt(p.reach)} i räckvidd · ${pct(p.goal)} målpoäng</span></div><p class="top-post-text">${esc(short(p.text,220)||'Inläggstext saknas i exporten.')}</p><p class="top-post-analysis"><strong>Varför tror vi att inlägget gick så bra?</strong><br>${esc(topReason(p))}</p><a class="top-post-link" href="${safeUrl(p.url)}" target="_blank" rel="noopener">Öppna inlägget</a></div></article>`}
function render(){const sum=summaries(),dates=state.posts.map(p=>p.date).filter(Boolean).sort((a,b)=>a-b),fb=state.posts.filter(p=>p.channel==='Facebook'),ig=state.posts.filter(p=>p.channel==='Instagram');$('qualityGrid').innerHTML=`<div class="quality-item facebook-card"><strong>${fmt(fb.length)}</strong><span>Facebook-inlägg</span></div><div class="quality-item instagram-card"><strong>${fmt(ig.length)}</strong><span>Instagram-inlägg</span></div><div class="quality-item"><strong>${iso(dates[0])}–${iso(dates.at(-1))}</strong><span>dataperiod</span></div><div class="quality-item"><strong>${state.posts.filter(p=>!p.url).length}</strong><span>rader utan permalänk</span></div>`;$('kpiGrid').innerHTML=sum.map(s=>`<div class="kpi ${s.channel==='Facebook'?'facebook-card':'instagram-card'}"><strong>${fmt(s.medianReach)}</strong><span>${s.channel} medianräckvidd · ${fmt(s.organic)} analysbara</span></div>`).join('')+`<div class="kpi"><strong>${Math.round(state.weights.reach*100)}/${Math.round(state.weights.engagement*100)}</strong><span>målmodell räckvidd/engagemang</span></div><div class="kpi instagram-card"><strong>${state.posts.filter(p=>p.channel==='Instagram'&&p.distribution==='Ej specificerad').length}</strong><span>Instagram med okänd distribution</span></div>`;for(const channel of['Facebook','Instagram']){const key=channel==='Facebook'?'facebook':'instagram',rows=formatRows().filter(r=>r.channel===channel);$(`${key}FormatTable`).querySelector('tbody').innerHTML=rows.map(r=>`<tr><td>${r.format}</td><td>${fmt(r.count)}</td><td>${fmt(r.reach)}</td><td>${pct(r.eng)}</td></tr>`).join('');$(`${key}TopCards`).innerHTML=topFive(channel).map(topCard).join('')}renderCorrections()}
function renderCorrections(){const rows=state.posts.filter(p=>p.channel==='Instagram').sort((a,b)=>b.reach-a.reach).slice(0,25);$('correctionsTable').querySelector('tbody').innerHTML=rows.map(p=>`<tr><td><strong>${esc(short(p.text,62)||p.format)}</strong><br><a href="${esc(safeUrl(p.url))}" target="_blank" rel="noreferrer">Öppna inlägg</a></td><td>${iso(p.date)}</td><td>${fmt(p.reach)}</td><td><select data-key="${encodeURIComponent(p.key)}" data-field="distribution"><option${p.distribution==='Ej specificerad'?' selected':''}>Ej specificerad</option><option${p.distribution==='Organisk egenpublicering'?' selected':''}>Organisk egenpublicering</option><option${p.distribution==='Instagram Collab'?' selected':''}>Instagram Collab</option><option${p.distribution==='Marknadsförd'?' selected':''}>Marknadsförd</option></select></td><td><input type="text" value="${esc(p.partner)}" data-key="${encodeURIComponent(p.key)}" data-field="partner" placeholder="Valfri partner"></td></tr>`).join('');$('correctionsNote').textContent='De 25 Instagraminläggen med högst räckvidd visas. Reglerna kan sparas och återanvändas nästa månad.';document.querySelectorAll('[data-key]').forEach(el=>el.addEventListener('change',saveCorrection))}
function saveCorrection(e){const key=decodeURIComponent(e.target.dataset.key),field=e.target.dataset.field;state.rules[key]??={};state.rules[key][field]=e.target.value;const post=state.posts.find(p=>p.key===key);if(post)post[field]=e.target.value;calculateScores();render()}
function period(){const d=state.posts.map(p=>p.date).filter(Boolean).sort((a,b)=>a-b);return d.length?`${iso(d[0])}–${iso(d.at(-1))}`:'okänd period'}function download(data,name,type='text/plain;charset=utf-8'){const blob=data instanceof Blob?data:new Blob([data],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
const normalizedHeaders=['Kanal','Publicerings-ID','Format','Publiceringstid','Månad','Veckodag','Text','Permalänk','Visningar','Räckvidd','Interaktioner','Engagemangsgrad','Reaktioner/Gilla','Kommentarer','Delningar','Sparningar','Klick','Nya följare','Marknadsförd räckvidd','Distribution','Tema (preliminärt)','Datakälla','Räckviddspoäng','Engagemangspoäng','Målpoäng','Följarkonvertering','Automatiskt redaktionellt syfte','Mänsklig korrigering','Slutligt redaktionellt syfte','Nyhetsvärde (text)','Lokal stolthet (text)','Mänsklig berättelse (text)','Praktisk nytta (text)','Distributionshypotes','Sekundär etikett','Nyhetsläge','Innehållskrok','Granskningsstatus','Sampubliceringspartner','Partnerstyrka'];
function normalizedValues(p){return[p.channel,p.id,p.format,p.date?iso(p.date):'',p.month,p.weekday,p.text,p.url,p.views,p.reach,p.interactions,p.engagement,p.likes,p.comments,p.shares,p.saves,p.clicks,p.follows,p.paid,p.distribution,p.theme,p.source,p.reachScore,p.engagementScore,p.goal,p.reach?p.follows/p.reach:null,p.contentDriver,'',p.finalDriver,p.news,p.pride,p.human,p.practical,p.hypothesis,p.theme==='Övrigt'?'':p.theme,p.timing,p.hypothesis,p.reviewStatus,p.partner,p.partnerStrength]}
function normalizedCsv(){return[normalizedHeaders.join(','),...state.posts.map(p=>normalizedValues(p).map(csvEscape).join(','))].join('\r\n')}
function knowledgeMarkdown(){const s=summaries(),f=formatRows(),formatSection=channel=>{const rows=f.filter(x=>x.channel===channel);return`## ${channel}\n| Format | Antal | Medianräckvidd | Medianengagemang |\n|---|---:|---:|---:|\n${rows.map(x=>`| ${x.format} | ${x.count} | ${fmt(x.reach)} | ${pct(x.eng)} |`).join('\n')}`};return`---\ntitle: AI-redaktionen – kanalinsikter för Visit Eskilstuna\nupdated: ${iso(new Date())}\ndata_period: ${period()}\n---\n\n# Syfte\nDenna fil bygger på Meta-exporter som analyserats lokalt i Kanalinsikter. Den ska användas som beslutsstöd, inte som en garanti för framtida resultat. Facebook och Instagram jämförs sida vid sida men rangordnas alltid var för sig.\n\n# Målmodell\nRäckvidd väger ${Math.round(state.weights.reach*100)} procent och engagemang ${Math.round(state.weights.engagement*100)} procent. Optimera primärt för organiskt innehåll.\n\n# Normalvärden per kanal\n${s.map(x=>`- ${x.channel}: ${fmt(x.count)} inlägg; organisk/analysbar medianräckvidd **${fmt(x.medianReach)}** och medianengagemang **${pct(x.medianEng)}**.`).join('\n')}\n\n# Format per kanal\n${formatSection('Facebook')}\n\n${formatSection('Instagram')}\n\n# Distributionsregler\n- Håll isär eget organiskt, Instagram Collab och marknadsfört.\n- Facebook med marknadsförd räckvidd exkluderas från organisk jämförelse.\n- Instagram med okänd distribution är en osäkerhet och ska verifieras när det påverkar slutsatsen.\n\n# Verifierade markeringar i denna export\n${state.posts.filter(p=>p.channel==='Instagram'&&p.distribution!=='Ej specificerad').map(p=>`- ${iso(p.date)}: ${p.distribution}${p.partner?` med ${p.partner}`:''} – ${p.url}`).join('\n')||'- Inga manuellt verifierade Instagrammarkeringar sparades.'}\n\n# Kvalitetsregel\nFaktakontrollera alltid aktuell information före publicering.\n`}
function changeLog(){return`# Ändringslogg – kanaldata\n\n- Uppdateringsdatum: ${iso(new Date())}\n- Dataperiod: ${period()}\n- Facebookposter: ${state.posts.filter(p=>p.channel==='Facebook').length}\n- Instagramposter: ${state.posts.filter(p=>p.channel==='Instagram').length}\n- Rader utan permalänk: ${state.posts.filter(p=>!p.url).length}\n- Manuellt markerade Instagraminlägg: ${state.posts.filter(p=>p.channel==='Instagram'&&p.distribution!=='Ej specificerad').length}\n\n## Kontroll\n- Rådata behandlades lokalt i webbläsaren.\n- Målmodell: ${Math.round(state.weights.reach*100)} % räckvidd / ${Math.round(state.weights.engagement*100)} % engagemang.\n- Organiskt, Collab och marknadsfört hölls isär där information fanns.\n\n## Kvarstående osäkerhet\n${state.posts.filter(p=>p.distribution==='Ej specificerad').length} Instagraminlägg saknar verifierad distributionsform.\n`}
function monthlyRows(){const months=[...new Set(state.posts.map(p=>p.month).filter(Boolean))].sort();return months.map(month=>{const fb=state.posts.filter(p=>p.month===month&&p.channel==='Facebook'&&eligible(p)),ig=state.posts.filter(p=>p.month===month&&p.channel==='Instagram'&&eligible(p));return{month,fbCount:fb.length,igCount:ig.length,fbReach:median(fb.map(p=>p.reach)),igReach:median(ig.map(p=>p.reach)),fbEng:median(fb.map(p=>p.engagement)),igEng:median(ig.map(p=>p.engagement))}})}
function chartPng(kind,title,rows){const canvas=document.createElement('canvas');canvas.width=900;canvas.height=360;const c=canvas.getContext('2d'),navy='#17324D',blue='#146C94',pink='#C83E78',grid='#D9E2E8';c.fillStyle='#FFFFFF';c.fillRect(0,0,900,360);c.fillStyle=navy;c.font='600 22px Arial';c.fillText(title,54,34);const left=66,top=58,w=790,h=230;let max=1;if(kind==='bar')max=Math.max(1,...rows.map(r=>r.value));else max=Math.max(1,...rows.flatMap(r=>[r.fb,r.ig]));c.strokeStyle=grid;c.lineWidth=1;c.font='12px Arial';for(let i=0;i<=5;i++){const y=top+h-h*i/5;c.beginPath();c.moveTo(left,y);c.lineTo(left+w,y);c.stroke();c.fillStyle='#62717D';c.textAlign='right';c.fillText(fmt(max*i/5),left-9,y+4)}if(kind==='bar'){const gap=w/rows.length,bw=Math.min(58,gap*.58);rows.forEach((r,i)=>{const x=left+gap*i+(gap-bw)/2,bh=h*r.value/max;c.fillStyle=r.channel==='Facebook'?blue:pink;c.fillRect(x,top+h-bh,bw,bh);c.save();c.translate(x+bw/2,top+h+17);c.rotate(-.42);c.fillStyle='#31424F';c.textAlign='right';c.font='11px Arial';c.fillText(r.label,0,0);c.restore()})}else{const colors=[blue,pink];[['fb','Facebook'],['ig','Instagram']].forEach(([key,label],series)=>{c.strokeStyle=colors[series];c.fillStyle=colors[series];c.lineWidth=3;c.beginPath();rows.forEach((r,i)=>{const x=left+(rows.length===1?w/2:i*w/(rows.length-1)),y=top+h-h*r[key]/max;i?c.lineTo(x,y):c.moveTo(x,y)});c.stroke();rows.forEach((r,i)=>{const x=left+(rows.length===1?w/2:i*w/(rows.length-1)),y=top+h-h*r[key]/max;c.beginPath();c.arc(x,y,3,0,Math.PI*2);c.fill()});c.fillRect(690+series*105,24,18,4);c.fillStyle='#31424F';c.textAlign='left';c.fillText(label,713+series*105,29)});c.fillStyle='#31424F';c.font='11px Arial';c.textAlign='center';rows.forEach((r,i)=>{if(i%2===0||rows.length<9){const x=left+(rows.length===1?w/2:i*w/(rows.length-1));c.fillText(r.month,x,top+h+20)}})}return canvas.toDataURL('image/png')}
